    $table->string('etag', 64)->nullable();
    $table->string('md5', 64)->nullable();
    $table->string('crc32c', 64)->nullable();
    $table->boolean('chunked')->default(false);
    $ids->reference(table: $table, column: 'encryption_key_id', nullable: true);
